targets.expr:
sum(
    last_over_time({level="INFO", server=~"$server", botType=~"$botType"} 
      | json bot_id="body.character.id", kamas="body.kamas.bruts" 
      | unwrap kamas | __error__="" [2d])
)
+
sum(
    last_over_time({level="INFO", server=~"$server", botType=~"$botType"} 
      | json bot_id="body.character.id", kamas="body.kamas.inBank" 
      | kamas > 0 
      | unwrap kamas | __error__="" [2d])
)
+
sum(
    last_over_time({level="INFO", server=~"$server", botType=~"$botType"} 
      | json bot_id="body.character.id", kamas="body.kamas.inHdv" 
      | kamas > 0 
      | unwrap kamas | __error__="" [2d])
)

sum by (bot_id, server, botType) (
  last_over_time(
    {level="INFO", server=~"$server", botType =~"$botType"} 
      | json bot_id="body.character.id", botType="body.botType", bruts="body.kamas.bruts"
      | unwrap bruts 
      | __error__=""
      [2d]
  )
)

sum(
    last_over_time({level="INFO", server=~"$server", botType=~"$botType"} 
      | json bot_id="body.character.id", kamas="body.kamas.bruts" 
      | unwrap kamas | __error__="" [2d])
)

sum by (bot_id, server, botType) (
  last_over_time(
    {level="INFO", server=~"$server", botType =~"$botType"} 
      | json bot_id="body.character.id", botType="body.botType", bruts="body.kamas.bruts"
      | unwrap bruts 
      | __error__=""
      [2d]
  )
)

(
  (
    sum(last_over_time({level="INFO", server=~"$server", botType=~"$botType"} | json k="body.kamas.bruts" | unwrap k | __error__="" [2d]))
  )
  - 
  (
    sum(last_over_time({level="INFO", server=~"$server", botType=~"$botType"} | json k="body.kamas.bruts" | unwrap k | __error__="" [2d] offset $__range))
  )
)
/
(
  sum(last_over_time({level="INFO", server=~"$server", botType=~"$botType"} | json k="body.kamas.bruts" | unwrap k | __error__="" [2d] offset $__range))
